# Official rubric (Hub's Quest Epoch 1, "Recursive Soundscapes")

Source: the challenge brief PDF. Solo, 24 hours, any AI coding agent allowed, but the repo must contain the full prompt chain and the agent's response to each prompt.

## Mandatory deliverables (all six must work in the deployed build)

1. A functional recursive algorithm with configurable parameters.
2. An interactive simulation or visualization.
3. A procedural music-generation system that uses the recursive process.
4. A user interface with parameter controls and audio playback.
5. A working audio export feature.
6. A polished, accessible experience designed around relaxation and enjoyment.

Guiding principle from the brief: "Make recursion audible. Make simulation beautiful. Make the experience relaxing."

## Scoring weights and what a 10/10 looks like

| Criterion | Weight | 10/10 looks like | Common ways to lose points |
| --- | --- | --- | --- |
| Relaxation & user experience | 35% | Within 10 seconds a stranger feels calmer. One tap to a finished piece. Nothing startles: fades everywhere, soft colours, slow motion. Works on a phone. Breathing, zen and sleep-timer tools feel native. | Abrupt starts or stops, clicks, loud peaks, busy UI, walls of sliders up front, tiny targets, broken mobile layout, jargon |
| Musical quality | 25% | Sounds like intentional ambient music: consonant harmony that moves, a melody with shape, phrases that breathe and resolve, warm timbres, a clean mix, no fatigue after 10 minutes. | Random pitches, out-of-key notes, square-wave harshness, mud in the low end, too many notes, no form, clipping |
| Creative use of recursion | 15% | The recursion's structure is audibly the musical structure (form, phrases, cadences on returns). Users can see which call is playing and hear depth-first vs breadth-first. More than one recursion. | Recursion only used to produce a list of numbers mapped to pitch; recursion invisible in the UI |
| Visual design | 10% | A coherent, distinctive look (tokens, type, palette per mood); the simulation is beautiful and synced to sound; 60 fps. | Generic template look, default component styling, desync, jank, flashing |
| Interaction & usability | 10% | Obvious controls with plain-language help, presets, keyboard shortcuts, shareable seeds, undo-safe changes, helpful empty and error states. | Unlabelled sliders, hidden features, no feedback on long actions (export), lost settings |
| Technical execution | 5% | Clean architecture, tests and CI, deployed demo, reliable export, no console errors, good performance, clear README. | Crashes, export that fails or is silent, memory leaks, no README |

## Self-check before submitting

- [ ] All six mandatory deliverables work on the deployed URL in a fresh browser profile.
- [ ] First minute: Begin → drone fades in → tree grows in sync → piece resolves. No console errors.
- [ ] Every mood sounds calm and consonant for 5 minutes on headphones and on phone speakers.
- [ ] Export WAV and MIDI work; the files open in a normal player or DAW.
- [ ] Keyboard-only run-through works; axe reports 0 serious/critical violations; reduced motion works.
- [ ] README has the live link, video link, mapping table, deliverables list, credits and AI-usage section.
- [ ] `ai-logs/` contains PROMPT_LOG.md, transcripts for every session, INDEX.md and the planning session.
// "Step inside a call": any branch of a recursion tree is itself a complete call of the same
// recursive function, so its subtree can be lifted out as a RecursionTrace of its own and played
// as a smaller, self-similar song. Pure and deterministic.

import { boundsOf, type RecursionTrace, type TraceNode } from './types';

/** how many levels a branch must have below it to be worth stepping into */
export const MIN_SUBTREE_LEVELS = 2;

/** the deepest ancestor-or-self of `nodeId` that still has at least MIN_SUBTREE_LEVELS below it */
export function enterableAncestor(trace: RecursionTrace, nodeId: number): number | null {
  let n: TraceNode | undefined = trace.nodes[nodeId];
  while (n && trace.maxDepth - n.depth < MIN_SUBTREE_LEVELS) n = n.parentId === null ? undefined : trace.nodes[n.parentId];
  // a real step needs to go below the current root and keep some recursion under it
  if (!n || n.depth === 0) return null;
  return n.id;
}

/** the subtree rooted at `nodeId`, re-indexed from 0, depths shifted so the branch becomes the trunk */
export function subtreeTrace(trace: RecursionTrace, nodeId: number): RecursionTrace {
  const root = trace.nodes[nodeId];
  if (!root) return trace;
  const { call, ret } = root.order;
  const events = trace.events.slice(call, ret + 1);
  // nodes in call order are exactly the nodes whose call event lies inside the root's call/return pair
  const ids = events.filter((e) => e.kind === 'call').map((e) => e.nodeId);
  const map = new Map<number, number>(ids.map((id, i) => [id, i]));
  const scale = root.size > 0 ? 1 / root.size : 1;
  // stand the branch upright around its base, so the call you stepped into becomes the new trunk
  const bx = root.points[0];
  const by = root.points[1];
  const ex = root.points[root.points.length - 2];
  const ey = root.points[root.points.length - 1];
  const rot = -Math.PI / 2 - Math.atan2(ey - by, ex - bx);
  const cos = Math.cos(rot);
  const sin = Math.sin(rot);
  const upright = (pts: number[]) => {
    const out = pts.slice();
    for (let k = 0; k < out.length; k += 2) {
      const dx = pts[k] - bx;
      const dy = pts[k + 1] - by;
      out[k] = bx + dx * cos - dy * sin;
      out[k + 1] = by + dx * sin + dy * cos;
    }
    return out;
  };
  const nodes: TraceNode[] = ids.map((id, i) => {
    const n = trace.nodes[id];
    return {
      ...n,
      id: i,
      parentId: id === nodeId || n.parentId === null ? null : (map.get(n.parentId) ?? null),
      childIds: n.childIds.map((c) => map.get(c)).filter((c): c is number => c !== undefined),
      depth: n.depth - root.depth,
      childIndex: id === nodeId ? 0 : n.childIndex,
      siblingCount: id === nodeId ? 1 : n.siblingCount,
      // relative to the new trunk, so the sub-song keeps full-length phrasing
      size: Math.min(1, n.size * scale),
      turn: id === nodeId ? 0 : n.turn,
      args: { ...n.args, depth: n.depth - root.depth },
      points: upright(n.points),
      order: { call: 0, ret: 0 },
    };
  });
  const remapped = events.map((e) => ({ kind: e.kind, nodeId: map.get(e.nodeId) ?? 0 }));
  remapped.forEach((e, i) => {
    if (e.kind === 'call') nodes[e.nodeId].order.call = i;
    else nodes[e.nodeId].order.ret = i;
  });
  let maxDepth = 0;
  for (const n of nodes) if (n.depth > maxDepth) maxDepth = n.depth;
  const parentOrigin = trace.originIds;
  return {
    ...trace,
    nodes,
    events: remapped,
    maxDepth,
    bounds: boundsOf(nodes),
    callCount: nodes.length,
    originIds: ids.map((id) => (parentOrigin ? parentOrigin[id] : id)),
  };
}

/** follow a path of origin ids (outermost first) from a full trace into nested sub-calls */
export function focusTrace(full: RecursionTrace, path: number[]): RecursionTrace {
  let t = full;
  for (const originId of path) {
    const local = t.originIds ? t.originIds.indexOf(originId) : originId;
    if (local <= 0 || !t.nodes[local]) break;
    t = subtreeTrace(t, local);
  }
  return t;
}
import { ChevronRight, ZoomOut } from 'lucide-react';
import { getWorld } from '../../core/worlds/registry';
import { useApp } from '../../state/store';

/** where you are in the recursion when you have stepped inside a call: a breadcrumb of frames */
export function CallTrail() {
  const focus = useApp((s) => s.focus);
  const full = useApp((s) => s.fullTrace);
  const trace = useApp((s) => s.trace);
  const stepOut = useApp((s) => s.stepOut);
  if (!focus.length || !full || !trace) return null;
  const world = getWorld(full.worldId);
  const outTo = (level: number) => {
    // pop frames until `level` remain
    const s = useApp.getState();
    const pops = s.focus.length - level;
    if (pops >= s.focus.length) s.stepOut(true);
    else {
      useApp.setState({ focus: s.focus.slice(0, level) });
      s.grow();
    }
  };
  return (
    <nav className="call-trail glass" aria-label="Calls you are inside">
      <ol>
        <li>
          <button className="crumb" onClick={() => outTo(0)}>
            Whole tree
          </button>
        </li>
        {focus.map((id, i) => {
          const n = full.nodes[id];
          const last = i === focus.length - 1;
          return (
            <li key={`${id}-${i}`}>
              <ChevronRight aria-hidden="true" />
              {last ? (
                <span className="crumb current" aria-current="location">
                  {n ? world.frameLabel(n) : 'branch'}
                </span>
              ) : (
                <button className="crumb" onClick={() => outTo(i + 1)}>
                  {n ? world.frameLabel(n) : 'branch'}
                </button>
              )}
            </li>
          );
        })}
      </ol>
      <span className="trail-note">{trace.nodes.length} calls, a song of their own</span>
      <button className="icon-btn" onClick={() => stepOut()} aria-label="Step out to the calling branch (O)" title="Step out (O)">
        <ZoomOut aria-hidden="true" />
      </button>
    </nav>
  );
}
